/// <reference types="node" />
import { readdirSync, readFileSync } from 'node:fs';
import { join, relative } from 'node:path';
import { describe, expect, it } from 'vite-plus/test';
import { root } from '@/test/stylesheets';

// Generated by Wayfinder (git-ignored) or test-only code.
const skippedDirectories = new Set(['actions', 'routes', 'wayfinder', 'test']);

function sourceFiles(directory: string): string[] {
    return readdirSync(directory, { withFileTypes: true }).flatMap((entry) => {
        const path = join(directory, entry.name);

        if (entry.isDirectory()) {
            return skippedDirectories.has(entry.name) ? [] : sourceFiles(path);
        }

        return /\.tsx?$/.test(entry.name) && !/\.test\.tsx?$/.test(entry.name)
            ? [path]
            : [];
    });
}

const files = sourceFiles(join(root, 'resources/js'));

function offences(pattern: RegExp): string[] {
    return files.flatMap((file) =>
        readFileSync(file, 'utf8')
            .split('\n')
            .flatMap((line, index) =>
                [...line.matchAll(pattern)].map(
                    (match) =>
                        `${relative(root, file)}:${index + 1} ${match[0]}`,
                ),
            ),
    );
}

describe('components use design tokens only', () => {
    it('scans the component sources', () => {
        expect(files.length).toBeGreaterThan(20);
    });

    it('contains no hex colour literal', () => {
        expect(
            offences(
                /(?<![\w&])#(?:[0-9a-f]{8}|[0-9a-f]{6}|[0-9a-f]{3,4})\b/gi,
            ),
        ).toEqual([]);
    });

    it("contains no colour from Tailwind's default palette", () => {
        const palette =
            'white|black|slate|gray|zinc|neutral|stone|red|orange|amber|' +
            'yellow|lime|green|emerald|teal|cyan|sky|blue|indigo|violet|' +
            'purple|fuchsia|pink|rose';
        const utilities =
            'bg|text|border|border-[trblxy]|outline|ring|ring-offset|fill|' +
            'stroke|from|via|to|divide|placeholder|caret|accent|decoration|' +
            'shadow';

        expect(
            offences(
                new RegExp(
                    `(?<![\\w-])(?:${utilities})-(?:${palette})(?:-\\d{2,3})?(?:/\\d+)?(?![\\w-])`,
                    'g',
                ),
            ),
        ).toEqual([]);
    });

    it('contains no colour function literal', () => {
        expect(offences(/\b(?:rgba?|hsla?|oklch|oklab)\(/g)).toEqual([]);
    });
});
